package gg.ironpath;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

final class IronPathApiClient
{
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final IronPathConfig config;

    @Inject
    IronPathApiClient(OkHttpClient httpClient, Gson gson, IronPathConfig config)
    {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;
    }

    void exchangeCode(String code, String characterName, Consumer<IronPathDtos.LinkResponse> callback)
    {
        IronPathDtos.LinkRequest payload = new IronPathDtos.LinkRequest(code, characterName, "0.4.2");
        post("/api/plugin/v1/link/exchange", null, gson.toJson(payload), response ->
        {
            IronPathDtos.LinkResponse result = response.body == null
                ? new IronPathDtos.LinkResponse()
                : gson.fromJson(response.body, IronPathDtos.LinkResponse.class);
            if (!response.success && result.error == null)
            {
                result.error = "The linking code was rejected.";
            }
            callback.accept(result);
        });
    }

    void sendSnapshot(String token, IronPathDtos.Snapshot snapshot, Consumer<Boolean> callback)
    {
        post("/api/plugin/v1/snapshot", token, gson.toJson(snapshot), response -> callback.accept(response.success));
    }

    void sendLoot(String token, List<IronPathDtos.LootEvent> events, Consumer<Boolean> callback)
    {
        post("/api/plugin/v1/loot-events", token, gson.toJson(new IronPathDtos.LootBatch(events)), response -> callback.accept(response.success));
    }

    void sendCollectionLog(String token, IronPathDtos.CollectionLogSync sync, Consumer<Boolean> callback)
    {
        post("/api/plugin/v1/collection-log", token, gson.toJson(sync), response -> callback.accept(response.success));
    }

    void fetchGoals(String token, Consumer<IronPathDtos.GoalsResponse> callback)
    {
        Request request = requestBuilder("/api/plugin/v1/goals", token).get().build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException error)
            {
                callback.accept(null);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response closeable = response)
                {
                    if (!response.isSuccessful() || response.body() == null)
                    {
                        callback.accept(null);
                        return;
                    }
                    callback.accept(gson.fromJson(response.body().charStream(), IronPathDtos.GoalsResponse.class));
                }
            }
        });
    }

    void updateGoalStatus(String token, String goalId, String status, Consumer<Boolean> callback)
    {
        Request request = requestBuilder("/api/plugin/v1/goals/" + goalId, token)
            .patch(RequestBody.create(JSON, gson.toJson(new IronPathDtos.GoalStatusUpdate(status))))
            .build();
        send(request, response -> callback.accept(response.success));
    }

    void unlink(String token, Consumer<Boolean> callback)
    {
        post("/api/plugin/v1/unlink", token, "{}", response -> callback.accept(response.success));
    }

    private Request.Builder requestBuilder(String path, String token)
    {
        String origin = normalizeApiOrigin(config.apiOrigin());
        if (origin == null) throw new IllegalStateException("Iron Path API origin must be a valid HTTPS URL");
        Request.Builder builder = new Request.Builder()
            .url(origin + path)
            .header("User-Agent", "IronPath-RuneLite/0.4.2");
        if (token != null && !token.isEmpty())
        {
            builder.header("Authorization", "Bearer " + token);
        }
        return builder;
    }

    static String normalizeApiOrigin(String value)
    {
        if (value == null) return null;
        HttpUrl origin = HttpUrl.parse(value.trim());
        if (origin == null || !"https".equals(origin.scheme())
            || !origin.username().isEmpty() || !origin.password().isEmpty()
            || origin.query() != null || origin.fragment() != null)
        {
            return null;
        }
        String normalized = origin.toString();
        while (normalized.endsWith("/")) normalized = normalized.substring(0, normalized.length() - 1);
        return normalized;
    }

    private void post(String path, String token, String json, Consumer<ApiResponse> callback)
    {
        Request request = requestBuilder(path, token).post(RequestBody.create(JSON, json)).build();
        send(request, callback);
    }

    private void send(Request request, Consumer<ApiResponse> callback)
    {
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException error)
            {
                callback.accept(new ApiResponse(false, null));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response closeable = response)
                {
                    callback.accept(new ApiResponse(response.isSuccessful(), response.body() == null ? null : response.body().string()));
                }
            }
        });
    }

    private static final class ApiResponse
    {
        private final boolean success;
        private final String body;
        private ApiResponse(boolean success, String body) { this.success = success; this.body = body; }
    }
}

package gg.ironpath;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.ScriptEvent;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

final class IronPathCollectionLog
{
    private static final int COLLECTION_DELAYED_TRANSMIT = 4100;
    private static final int COLLECTION_TAB_ENUM = 2102;
    private static final int TAB_PAGE_ENUM_PARAM = 683;
    private static final int PAGE_NAME_PARAM = 689;
    private static final int PAGE_ITEM_ENUM_PARAM = 690;
    private static final int SETTLE_TICKS = 3;
    private static final String[] CATEGORIES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};
    private static final Pattern PROGRESS_FRACTION = Pattern.compile("([0-9][0-9,]*)\\s*/\\s*([0-9][0-9,]*)");
    private static final Pattern NUMBER = Pattern.compile("[0-9][0-9,]*");

    private final Client client;
    private final Consumer<List<IronPathDtos.CollectionLogSection>> listener;
    private final List<PageDefinition> definitions = new ArrayList<>();
    private final Map<Integer, Integer> harvest = new HashMap<>();
    private final List<Integer> latestItems = new ArrayList<>();
    private IronPathDtos.CollectionLogProgress latestProgress;
    private boolean awaitingSearch;
    private boolean receiving;
    private int lastTransmitTick = -1;

    IronPathCollectionLog(Client client, Consumer<List<IronPathDtos.CollectionLogSection>> listener)
    {
        this.client = client;
        this.listener = listener;
    }

    void collectionOpened()
    {
        if (isAnotherPlayersLog()) return;
        loadDefinitions();
        awaitingSearch = false;
        receiving = false;
        harvest.clear();
        lastTransmitTick = -1;
    }

    boolean requestSync()
    {
        if (isAnotherPlayersLog() || !loadDefinitions()) return false;
        Widget search = client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE);
        if (search == null || search.isHidden()) return false;
        harvest.clear();
        receiving = true;
        awaitingSearch = true;
        lastTransmitTick = client.getTickCount();
        client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1,
            -1, "Search", null);
        client.runScript(2240);
        return true;
    }

    List<Integer> recentItemIds()
    {
        Widget latest = client.getWidget(InterfaceID.CollectionOverview.LATEST_ITEMS_DATA);
        if (latest == null) return new ArrayList<>(latestItems);
        Set<Integer> ids = new LinkedHashSet<>();
        collectItems(latest, ids);
        List<Integer> result = new ArrayList<>(ids);
        List<Integer> limited = result.size() <= 10 ? result : new ArrayList<>(result.subList(0, 10));
        latestItems.clear();
        latestItems.addAll(limited);
        return new ArrayList<>(latestItems);
    }

    IronPathDtos.CollectionLogProgress globalProgress()
    {
        loadDefinitions();
        int definitionTotal = uniqueDefinitionItemCount();
        IronPathDtos.CollectionLogProgress progress = findProgress(
            client.getWidget(InterfaceID.Collection.HEADER_TEXT), definitionTotal, null);
        progress = findProgress(client.getWidget(InterfaceID.Collection.UNIVERSE), definitionTotal, progress);
        progress = findProgress(client.getWidget(InterfaceID.CollectionOverview.UNIVERSE), definitionTotal, progress);
        if (progress == null)
        {
            Integer obtained = widgetNumber(client.getWidget(InterfaceID.CollectionOverview.PROGRESS_LEFT_TEXT));
            Integer total = widgetNumber(client.getWidget(InterfaceID.CollectionOverview.PROGRESS_RIGHT_TEXT));
            if (validProgress(obtained, total, definitionTotal))
            {
                progress = new IronPathDtos.CollectionLogProgress(obtained, total);
            }
        }
        if (progress != null) latestProgress = progress;
        return latestProgress;
    }

    boolean onScriptPreFired(int scriptId, ScriptEvent event)
    {
        if (scriptId != COLLECTION_DELAYED_TRANSMIT || !awaitingSearch || isAnotherPlayersLog()) return false;
        Object[] arguments = event == null ? null : event.getArguments();
        if (arguments == null || arguments.length < 3 || !(arguments[1] instanceof Integer) || !(arguments[2] instanceof Integer)) return false;
        int itemId = (Integer) arguments[1];
        int quantity = (Integer) arguments[2];
        if (itemId <= 0 || quantity <= 0) return false;
        receiving = true;
        harvest.put(itemId, quantity);
        lastTransmitTick = client.getTickCount();
        return true;
    }

    boolean onGameTick()
    {
        if (!receiving || lastTransmitTick < 0 || lastTransmitTick + SETTLE_TICKS >= client.getTickCount()) return false;
        List<IronPathDtos.CollectionLogSection> sections = snapshot();
        receiving = false;
        awaitingSearch = false;
        lastTransmitTick = -1;
        if (!sections.isEmpty()) listener.accept(sections);
        return !sections.isEmpty();
    }

    int sectionCount()
    {
        return definitions.size();
    }

    boolean isAwaitingSearch()
    {
        return awaitingSearch;
    }

    void reset()
    {
        definitions.clear();
        harvest.clear();
        latestItems.clear();
        latestProgress = null;
        awaitingSearch = false;
        receiving = false;
        lastTransmitTick = -1;
    }

    private boolean loadDefinitions()
    {
        EnumComposition tabEnum = client.getEnum(COLLECTION_TAB_ENUM);
        int[] tabStructIds = tabEnum == null ? null : tabEnum.getIntVals();
        if (tabStructIds == null || tabStructIds.length == 0) return false;
        List<PageDefinition> loaded = new ArrayList<>();
        for (int tabIndex = 0; tabIndex < Math.min(tabStructIds.length, CATEGORIES.length); tabIndex++)
        {
            StructComposition tab = client.getStructComposition(tabStructIds[tabIndex]);
            EnumComposition pages = client.getEnum(tab.getIntValue(TAB_PAGE_ENUM_PARAM));
            int[] pageStructIds = pages == null ? null : pages.getIntVals();
            if (pageStructIds == null) continue;
            for (int pageStructId : pageStructIds)
            {
                StructComposition page = client.getStructComposition(pageStructId);
                EnumComposition items = client.getEnum(page.getIntValue(PAGE_ITEM_ENUM_PARAM));
                int[] itemIds = items == null ? null : items.getIntVals();
                String rawName = page.getStringValue(PAGE_NAME_PARAM);
                String name = rawName == null ? "" : Text.removeTags(rawName).trim();
                if (itemIds != null && itemIds.length > 0 && !name.isEmpty()) loaded.add(new PageDefinition(CATEGORIES[tabIndex], name, itemIds));
            }
        }
        definitions.clear();
        definitions.addAll(loaded);
        return !definitions.isEmpty();
    }

    private List<IronPathDtos.CollectionLogSection> snapshot()
    {
        String capturedAt = Instant.now().toString();
        List<IronPathDtos.CollectionLogSection> sections = new ArrayList<>();
        for (PageDefinition definition : definitions)
        {
            List<IronPathDtos.CollectionLogSlot> slots = new ArrayList<>();
            int obtained = 0;
            int slotOrder = 0;
            Set<Integer> unique = new LinkedHashSet<>();
            for (int itemId : definition.itemIds) if (itemId > 0) unique.add(itemId);
            for (int itemId : unique)
            {
                int quantity = harvest.getOrDefault(itemId, 0);
                boolean unlocked = quantity > 0;
                if (unlocked) obtained++;
                slots.add(new IronPathDtos.CollectionLogSlot(itemId, quantity, unlocked, slotOrder++));
            }
            sections.add(new IronPathDtos.CollectionLogSection(
                key(definition.category, definition.name), definition.category, definition.name,
                obtained, slots.size(), capturedAt, slots));
        }
        return sections;
    }

    private boolean isAnotherPlayersLog()
    {
        return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
    }

    private static void collectItems(Widget widget, Set<Integer> itemIds)
    {
        if (widget.getItemId() > 0) itemIds.add(widget.getItemId());
        collectItems(widget.getDynamicChildren(), itemIds);
        collectItems(widget.getStaticChildren(), itemIds);
        collectItems(widget.getNestedChildren(), itemIds);
    }

    private static void collectItems(Widget[] widgets, Set<Integer> itemIds)
    {
        if (widgets == null) return;
        for (Widget widget : widgets)
        {
            if (widget != null) collectItems(widget, itemIds);
        }
    }

    private int uniqueDefinitionItemCount()
    {
        Set<Integer> ids = new LinkedHashSet<>();
        for (PageDefinition definition : definitions)
        {
            for (int itemId : definition.itemIds) if (itemId > 0) ids.add(itemId);
        }
        return ids.size();
    }

    private static IronPathDtos.CollectionLogProgress findProgress(
        Widget widget, int definitionTotal, IronPathDtos.CollectionLogProgress best)
    {
        if (widget == null) return best;
        String text = Text.removeTags(widget.getText() == null ? "" : widget.getText());
        IronPathDtos.CollectionLogProgress parsed = parseProgressText(text, definitionTotal);
        if (parsed != null && (best == null || parsed.totalCount > best.totalCount)) best = parsed;
        best = findProgress(widget.getDynamicChildren(), definitionTotal, best);
        best = findProgress(widget.getStaticChildren(), definitionTotal, best);
        return findProgress(widget.getNestedChildren(), definitionTotal, best);
    }

    static IronPathDtos.CollectionLogProgress parseProgressText(String text, int definitionTotal)
    {
        IronPathDtos.CollectionLogProgress best = null;
        Matcher matcher = PROGRESS_FRACTION.matcher(text);
        while (matcher.find())
        {
            Integer obtained = parseNumber(matcher.group(1));
            Integer total = parseNumber(matcher.group(2));
            if (validProgress(obtained, total, definitionTotal)
                && (best == null || total > best.totalCount))
            {
                best = new IronPathDtos.CollectionLogProgress(obtained, total);
            }
        }
        return best;
    }

    private static IronPathDtos.CollectionLogProgress findProgress(
        Widget[] widgets, int definitionTotal, IronPathDtos.CollectionLogProgress best)
    {
        if (widgets == null) return best;
        for (Widget widget : widgets) best = findProgress(widget, definitionTotal, best);
        return best;
    }

    private static Integer widgetNumber(Widget widget)
    {
        if (widget == null || widget.getText() == null) return null;
        Matcher matcher = NUMBER.matcher(Text.removeTags(widget.getText()));
        return matcher.find() ? parseNumber(matcher.group()) : null;
    }

    private static Integer parseNumber(String value)
    {
        try
        {
            return Integer.parseInt(value.replace(",", ""));
        }
        catch (NumberFormatException ignored)
        {
            return null;
        }
    }

    private static boolean validProgress(Integer obtained, Integer total, int definitionTotal)
    {
        if (obtained == null || total == null || obtained < 0 || total <= 0 || obtained > total) return false;
        if (definitionTotal <= 0) return true;
        int tolerance = Math.max(32, definitionTotal / 20);
        return Math.abs(total - definitionTotal) <= tolerance;
    }

    private static String key(String category, String name)
    {
        return (category + ":" + name).toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", "-").replaceAll("(^-|-$)", "");
    }

    private static final class PageDefinition
    {
        private final String category;
        private final String name;
        private final int[] itemIds;

        private PageDefinition(String category, String name, int[] itemIds)
        {
            this.category = category;
            this.name = name;
            this.itemIds = itemIds;
        }
    }
}

package gg.ironpath;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(IronPathConfig.GROUP)
public interface IronPathConfig extends Config
{
    String GROUP = "ironpath";
    String DEFAULT_API_ORIGIN = "https://www.ironpathosrs.com";

    @ConfigSection(
        name = "Connection",
        description = "Link this RuneLite profile to Iron Path",
        position = 0,
        closedByDefault = true
    )
    String connectionSection = "connection";

    @ConfigSection(
        name = "Sync",
        description = "Choose when Iron Path synchronizes account data",
        position = 1,
        closedByDefault = true
    )
    String syncSection = "sync";

    @ConfigSection(
        name = "Sidebar display",
        description = "Choose which sections appear in the Iron Path sidebar",
        position = 2,
        closedByDefault = true
    )
    String sidebarSection = "sidebar";

    @ConfigItem(
        keyName = "apiOrigin",
        name = "API origin",
        description = "HTTPS web application origin that receives synchronized Iron Path data; changing it requires relinking",
        position = 0,
        section = connectionSection
    )
    default String apiOrigin()
    {
        return DEFAULT_API_ORIGIN;
    }

    @ConfigItem(
        keyName = "linkingCode",
        name = "Linking code",
        description = "Single-use code generated by the Iron Path website",
        warning = "Linking sends your RuneScape name, account mode, levels and XP, quests, bank, inventory, "
            + "equipment, loot, kill counts, Collection Log, and goal progress to the configured Iron Path API origin.",
        position = 1,
        section = connectionSection
    )
    default String linkingCode()
    {
        return "";
    }

    @ConfigItem(
        keyName = "autoSync",
        name = "Automatic sync",
        description = "Refresh goals every 15 seconds, sync progress every two minutes, and sync bank changes shortly after they occur",
        warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
        position = 0,
        section = syncSection
    )
    default boolean autoSync()
    {
        return false;
    }

    @ConfigItem(
        keyName = "showConnection",
        name = "Show connection",
        description = "Show character linking status and the Relink button in the sidebar",
        position = 0,
        section = sidebarSection
    )
    default boolean showConnection()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showSyncActivity",
        name = "Show sync activity",
        description = "Show session kills, pending uploads, last sync time, and manual sync controls",
        position = 1,
        section = sidebarSection
    )
    default boolean showSyncActivity()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showCollectionLog",
        name = "Show Collection Log",
        description = "Show Collection Log detection, last-sync status, and its sync control",
        position = 2,
        section = sidebarSection
    )
    default boolean showCollectionLog()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showRecentCollections",
        name = "Show recent collections",
        description = "Show recently captured Collection Log items",
        position = 3,
        section = sidebarSection
    )
    default boolean showRecentCollections()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showRecentKills",
        name = "Show recent kills",
        description = "Show recent tracked NPC kills",
        position = 4,
        section = sidebarSection
    )
    default boolean showRecentKills()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showGoals",
        name = "Show goals",
        description = "Show active and completed Iron Path goals",
        position = 5,
        section = sidebarSection
    )
    default boolean showGoals()
    {
        return true;
    }
}

package gg.ironpath;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class IronPathDtos
{
    private IronPathDtos() {}

    static final class LinkRequest
    {
        final String code;
        final String characterName;
        final String clientVersion;

        LinkRequest(String code, String characterName, String clientVersion)
        {
            this.code = code;
            this.characterName = characterName;
            this.clientVersion = clientVersion;
        }
    }

    static final class LinkResponse
    {
        String token;
        String characterId;
        String error;
    }

    static final class SkillRecord
    {
        final String skill;
        final int level;
        final int xp;

        SkillRecord(String skill, int level, int xp)
        {
            this.skill = skill;
            this.level = level;
            this.xp = xp;
        }
    }

    static final class QuestRecord
    {
        final String quest;
        final String state;

        QuestRecord(String quest, String state)
        {
            this.quest = quest;
            this.state = state;
        }
    }

    static final class ItemRecord
    {
        final int itemId;
        final int quantity;
        final String container;

        ItemRecord(int itemId, int quantity, String container)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.container = container;
        }
    }

    static final class Snapshot
    {
        final String capturedAt;
        final String characterName;
        final String accountType;
        final int combatLevel;
        final List<SkillRecord> skills;
        final List<QuestRecord> quests;
        final List<ItemRecord> items;
        final List<AbsoluteKillCount> killCounts;

        Snapshot(String capturedAt, String characterName, String accountType, int combatLevel, List<SkillRecord> skills,
                 List<QuestRecord> quests, List<ItemRecord> items, List<AbsoluteKillCount> killCounts)
        {
            this.capturedAt = capturedAt;
            this.characterName = characterName;
            this.accountType = accountType;
            this.combatLevel = combatLevel;
            this.skills = skills;
            this.quests = quests;
            this.items = items;
            this.killCounts = killCounts;
        }
    }

    static final class AbsoluteKillCount
    {
        final String sourceName;
        final int count;
        final String capturedAt;

        AbsoluteKillCount(String sourceName, int count, String capturedAt)
        {
            this.sourceName = sourceName;
            this.count = count;
            this.capturedAt = capturedAt;
        }
    }

    static final class LootItem
    {
        final int itemId;
        final int quantity;

        LootItem(int itemId, int quantity)
        {
            this.itemId = itemId;
            this.quantity = quantity;
        }
    }

    static final class LootEvent
    {
        final String eventId;
        final String occurredAt;
        final int npcId;
        final String npcName;
        final List<LootItem> items;

        LootEvent(String eventId, String occurredAt, int npcId, String npcName, List<LootItem> items)
        {
            this.eventId = eventId;
            this.occurredAt = occurredAt;
            this.npcId = npcId;
            this.npcName = npcName;
            this.items = items;
        }
    }

    static final class LootBatch
    {
        final List<LootEvent> events;
        LootBatch(List<LootEvent> events) { this.events = events; }
    }

    static final class KillCount
    {
        final int npcId;
        String npcName;
        int count;
        String lastKilledAt;

        KillCount(int npcId, String npcName, int count, String lastKilledAt)
        {
            this.npcId = npcId;
            this.npcName = npcName;
            this.count = count;
            this.lastKilledAt = lastKilledAt;
        }

        void record(String name, String occurredAt)
        {
            count++;
            if (name != null && !name.trim().isEmpty()) npcName = name;
            lastKilledAt = occurredAt;
        }
    }

    static final class GoalSummary
    {
        String id;
        String kind;
        String title;
        String status;
        boolean isPublic;
        GoalSettings settings;
    }

    static final class GoalStatusUpdate
    {
        final String status;

        GoalStatusUpdate(String status)
        {
            this.status = status;
        }
    }

    static final class GoalSettings
    {
        String monster;
        String targetItemName;
        String skill;
        String state;
        int dropRate;
        int startingKc;
        int observedKc;
        int currentLevel;
        int targetLevel;
        int currentXp;
        int targetXp;
        List<Integer> npcIds = Collections.emptyList();
    }

    static final class CollectionLogSlot
    {
        final int itemId;
        final int quantity;
        final boolean obtained;
        final int slotOrder;

        CollectionLogSlot(int itemId, int quantity, boolean obtained, int slotOrder)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.obtained = obtained;
            this.slotOrder = slotOrder;
        }
    }

    static final class CollectionLogSection
    {
        final String key;
        final String category;
        final String name;
        final int obtainedCount;
        final int totalCount;
        final String capturedAt;
